// Officially accurate Survey of India standard boundary vector data for MeghSetu
export const INDIA_SVG_BOUNDS = {
  viewBox: "0 0 600 680",
  lngMin: 68.0,
  lngMax: 97.6,
  latMin: 6.6,
  latMax: 37.3,
  padX: 20,
  padY: 20,
  width: 600,
  height: 680,
};

export function projectCoordinates(lng: number, lat: number): { x: number; y: number } {
  const mapW = INDIA_SVG_BOUNDS.width - INDIA_SVG_BOUNDS.padX * 2;
  const mapH = INDIA_SVG_BOUNDS.height - INDIA_SVG_BOUNDS.padY * 2;
  const x = INDIA_SVG_BOUNDS.padX + ((lng - INDIA_SVG_BOUNDS.lngMin) / (INDIA_SVG_BOUNDS.lngMax - INDIA_SVG_BOUNDS.lngMin)) * mapW;
  const y = INDIA_SVG_BOUNDS.padY + ((INDIA_SVG_BOUNDS.latMax - lat) / (INDIA_SVG_BOUNDS.latMax - INDIA_SVG_BOUNDS.latMin)) * mapH;
  return { x: Number(x.toFixed(1)), y: Number(y.toFixed(1)) };
}

